/*Table structure for table `ba_check_log` */

DROP TABLE IF EXISTS `ba_check_log`;

CREATE TABLE `ba_check_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `check_plan_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '计划',
  `time` time DEFAULT NULL COMMENT '发现时间',
  `area` enum('A','B','C','D') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'A' COMMENT '区域:A=A,B=B,C=C,D=D',
  `bird_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '鸟种',
  `min_num` int(10) NOT NULL DEFAULT '0' COMMENT '数量最小值',
  `max_num` int(10) NOT NULL DEFAULT '0' COMMENT '数量最大值',
  `min_height` int(10) NOT NULL DEFAULT '0' COMMENT '最低高度',
  `max_height` int(10) NOT NULL DEFAULT '0' COMMENT '最大高度',
  `active_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '鸟类活动行为:0=跑道滑行道道面停留,1=跑道滑行道上空飞行,2=跑道端安全区飞行觅食,3=升级带区域飞行觅食',
  `cuoshi` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '采取驱鸟措施:0=音频,1=猎枪',
  `result` enum('A','B','C','D') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'A' COMMENT '效果:A=A,B=B,C=C,D=D',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='巡视记录';

/*Data for the table `ba_check_log` */

