/*Table structure for table `ba_check_plan` */

DROP TABLE IF EXISTS `ba_check_plan`;

CREATE TABLE `ba_check_plan` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `date` date DEFAULT NULL COMMENT '日期',
  `admin_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '巡视人员',
  `weather` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '天气',
  `car_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '车辆',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='巡视计划';

