/*Table structure for table `ba_protocel` */

DROP TABLE IF EXISTS `ba_protocel`;

CREATE TABLE `ba_protocel` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '协议名称',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '富文本',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '状态:0=禁用,1=启用',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='协议管理';

/*Data for the table `ba_protocel` */

